command:
// ==========================================
// ⚙️ LUNAS WIRKUNG: FALSCHE FÄHRTE (V13 Ready)
// ==========================================

(async () => {
    // ============================================================
    // 0. Framework laden & Wirkungsende-Hook registrieren
    // ============================================================
    const fwMacro = await fromUuid("Compendium.dsk-havena-und-umland.makros.Macro.fHQ2OuDo3Fe3spBn");
    if (fwMacro) { await fwMacro.execute(); }

    if (typeof DSK === "undefined") {
        ui.notifications.error("Das DSK-Framework konnte nicht geladen werden!");
        return;
    }
    const DSK_FW = globalThis.DSK || DSK;

    const gabenName = "Falsche Fährte";
    const ahne = "Rondra";
    const finalEffektName = `${gabenName} (${ahne})`;

    // Hilfsfunktion: Finde alle Spieler-IDs, denen ein Akteur gehört
    const getOwners = (act) => {
        if (!act) return [];
        const ownership = act.ownership || act.permission || {};
        return Object.entries(ownership)
            .filter(([id, lvl]) => lvl === 3 && id !== "default")
            .map(([id]) => id);
    };

    if (DSK_FW.EffektEnde) {
        DSK_FW.EffektEnde.Register(
            "rondraFalscheFaehrte", 
            finalEffektName, 
            "Die illusionäre Fährte verblasst, und es werden wieder die echten Spuren hinterlassen."
        );
    }

    // ============================================================
    // 1. Caster-Ermittlung & QS aus Flag auslesen
    // ============================================================
    const actorObj = (typeof testData !== "undefined" && testData?.actor) || 
                     (typeof testData !== "undefined" && testData?.speaker?.actor ? game.actors.get(testData.speaker.actor) : null) || 
                     (typeof testData !== "undefined" && testData?.speaker?.token ? canvas.tokens.get(testData.speaker.token)?.actor : null) || 
                     actor || 
                     canvas.tokens.controlled[0]?.actor || 
                     game.user.character;

    if (!actorObj) {
        ui.notifications.warn("Kein Akteur gefunden! Bitte wähle einen Token aus.");
        return;
    }

    // QS aus dem Flag auslesen, das vom Start-Makro gesetzt wurde (mit Fallback)
    let qsWert = actorObj.getFlag("world", "letzteGabenQS") || 1;
    if (actorObj.getFlag("world", "letzteGabenQS")) {
        await actorObj.unsetFlag("world", "letzteGabenQS");
    }

    try {
        if (typeof testData !== "undefined" && testData) {
            const parsedQs = Number(testData?.result?.QL || testData?.qualityStep);
            if (!isNaN(parsedQs) && parsedQs > 0) {
                qsWert = parsedQs;
            }
        }
    } catch (e) {}

    if (qsWert <= 0) {
        return ui.notifications.warn("Die Probe ist fehlgeschlagen.");
    }

    const dauerMinuten = qsWert * 10;
    const dauerSekunden = dauerMinuten * 60;
    const dauerText = `${dauerMinuten} Minuten (QS ${qsWert})`;

    const basisBeschreibung = `Statt der eigenen Spuren hinterlässt das Rondrakind Spuren eines anderen Tieres ähnlicher Größe, beispielsweise eines kleinen Hundes, einer großen Ratte oder eines Hasen.`;
    const targetName = DSK_FW.ResolveTokenName(actorObj);

    // ============================================================
    // 2. Effekt anlegen
    // ============================================================
    try {
        let alterEffekt = actorObj.effects.find(e => e.name === finalEffektName);
        if (alterEffekt) await alterEffekt.delete();

        await actorObj.createEmbeddedDocuments("ActiveEffect", [{
            name: finalEffektName,
            icon: DSK_FW.Symbol(ahne),
            description: basisBeschreibung,
            disabled: false,
            origin: actorObj.uuid,
            duration: { seconds: dauerSekunden }
        }]);

        // ============================================================
        // 3. WHISPER-EMPFÄNGER & CHAT-KARTE (System-Sprecher)
        // ============================================================
        let ownerIds = new Set(game.users.filter(u => u.isGM).map(u => u.id));
        getOwners(actorObj).forEach(id => ownerIds.add(id));
        const whisperEmpfaenger = Array.from(ownerIds).filter(id => game.users.get(id));

        const erfolgHtml = `
            <div style="margin-top: 10px; margin-bottom: 10px;">
                <p style="margin-bottom: 5px;"><span style="color:#18940F; font-weight:bold;">Erfolg</span></p>
                <ul class="dsklist" style="margin-top:0; font-weight:normal;">
                    <li>${targetName}</li>
                </ul>
            </div>
        `;

        await ChatMessage.create({
            speaker: { alias: "System" },
            whisper: whisperEmpfaenger,
            content: `
                <div style="font-family: 'Signika', sans-serif;">
                    ${DSK_FW.UI.Header(gabenName, DSK_FW.Symbol(ahne))}
                    <div class="dskbox2" style="margin-top:10px;">
                        <p><b>Gabenwirkung:</b></p>
                        <p>${basisBeschreibung}</p>
                        <hr>
                        ${erfolgHtml}
                        <hr>
                        <p style="text-align:center; font-weight:bold;">
                            Wirkungsdauer:<br>${dauerText}
                        </p>
                    </div>
                </div>
            `
        });

        // --- EFFEKT-BESCHREIBUNG AUF DEM TOKEN AKTUALISIEREN ---
        const kompletterEffektText = `
            <b>Gabenwirkung:</b><br>${basisBeschreibung}<br><hr>
            <b>Erfolg:</b><br>• ${targetName}<br><hr>
            <b>Wirkungsdauer: ${dauerText}</b>
        `.trim();

        for (const effect of actorObj.effects) {
            if (effect.name === finalEffektName) {
                try {
                    await effect.update({ description: kompletterEffektText });
                } catch (err) {}
            }
        }

    } catch (e) {
        console.warn(`Effekt konnte nicht angewendet werden:`, e);
    }
})();
